import { useMemo, useState } from "react";
import { Link } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { ChevronRight, Clock3, MapPin, Package, RotateCcw, Truck } from "lucide-react";
import { formatUZS } from "../data/mock";
import { useShop } from "../lib/store";
import { EmptyState, MapView, Modal, OrderProgress, OrderStatusBadge, cn } from "../lib/ui";
const tabs = [
  { key: "all", label: "all" },
  { key: "active", label: "activeOrder" },
  { key: "delivered", label: "statusDelivered" },
  { key: "cancelled", label: "statusCancelled" }
];
export const OrdersPage = () => {
  const { t } = useTranslation();
  const { orders, addToCart, pushToast } = useShop();
  const [tab, setTab] = useState("all");
  const [selected, setSelected] = useState(null);
  const filtered = useMemo(() => {
    if (tab === "active") return orders.filter((o) => ["confirmed", "preparing", "delivering"].includes(o.status));
    if (tab === "delivered") return orders.filter((o) => o.status === "delivered");
    if (tab === "cancelled") return orders.filter((o) => o.status === "cancelled");
    return orders;
  }, [orders, tab]);
  const active = orders.find((o) => ["confirmed", "preparing", "delivering"].includes(o.status));
  const reorder = (order) => {
    order.items.forEach((item) => addToCart(item.productId, item.qty));
    pushToast(t("addedToCart"), "success");
  };
  return <div className="container-page py-5 sm:py-7">
      <div className="mb-5">
        <h1 className="font-display text-2xl font-extrabold sm:text-3xl">{t("myOrders")}</h1>
        <p className="mt-1 text-xs text-[var(--muted)]">{t("profileSubtitle")}</p>
      </div>

      {active && <div className="card mb-5 overflow-hidden">
          <div className="grid gap-4 p-4 sm:p-5 lg:grid-cols-[1fr_1.1fr] lg:items-center">
            <div>
              <div className="flex items-center justify-between gap-2">
                <span className="badge bg-brand-500/15 text-brand-700 dark:text-brand-300"><span className="h-1.5 w-1.5 animate-pulse rounded-full bg-brand-500" /> {t("activeOrder")}</span>
                <OrderStatusBadge status={active.status} />
              </div>
              <h2 className="mt-2 font-display text-lg font-extrabold">#{active.id}</h2>
              <p className="mt-1 flex items-center gap-1 text-[11px] text-[var(--muted)]"><MapPin size={11} /> {active.address}</p>
              <div className="mt-3 rounded-xl bg-[var(--surface-2)] p-3">
                <OrderProgress status={active.status} />
              </div>
              <div className="mt-3 flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <span className="flex h-9 w-9 items-center justify-center rounded-full bg-amber-400/20 text-base">🛵</span>
                  <div>
                    <p className="text-[10px] font-bold text-[var(--muted)]">{t("courier")}</p>
                    <p className="text-[11px] font-extrabold">{active.courier}</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-[10px] font-bold text-[var(--muted)]">{t("estimatedArrival")}</p>
                  <p className="text-sm font-extrabold text-brand-600 dark:text-brand-400">{active.eta}</p>
                </div>
              </div>
              <Link to={`/tracking/${active.id}`} className="btn-primary mt-3 w-full btn-sm"><Truck size={14} /> {t("trackOrder")}</Link>
            </div>
            <MapView courierName={active.courier} eta={active.eta} address={active.address} />
          </div>
        </div>}

      <div className="mb-4 flex gap-1.5 overflow-x-auto pb-1 no-scrollbar">
        {tabs.map((item) => <button
    key={item.key}
    onClick={() => setTab(item.key)}
    className={cn("chip shrink-0", tab === item.key && "chip-active")}
  >
            {t(item.label)}
            <span className={cn("rounded-full px-1.5 text-[9px]", tab === item.key ? "bg-white/20" : "bg-[var(--surface-2)]")}>
              {item.key === "all" ? orders.length : item.key === "active" ? orders.filter((o) => ["confirmed", "preparing", "delivering"].includes(o.status)).length : orders.filter((o) => o.status === item.key).length}
            </span>
          </button>)}
      </div>

      {filtered.length === 0 ? <EmptyState
    icon={<Package size={28} />}
    title={t("emptyOrdersTitle")}
    description={t("emptyOrdersDesc")}
    action={<Link to="/catalog" className="btn-primary btn-sm">{t("emptyCartBtn")}</Link>}
  /> : <div className="space-y-3">
          {filtered.map((order) => <div key={order.id} className="card p-4">
              <div className="flex flex-wrap items-start justify-between gap-2">
                <div>
                  <div className="flex items-center gap-2">
                    <p className="font-display text-sm font-extrabold">#{order.id}</p>
                    <OrderStatusBadge status={order.status} />
                  </div>
                  <p className="mt-1 flex items-center gap-2 text-[10px] font-semibold text-[var(--muted)]"><Clock3 size={10} /> {order.date} · {order.items.length} {t("itemsCount")}</p>
                </div>
                <p className="font-display text-base font-extrabold text-brand-700 dark:text-brand-400">{formatUZS(order.total)}</p>
              </div>

              <div className="mt-3 flex items-center justify-between gap-3">
                <div className="flex items-center gap-1.5">
                  {order.items.slice(0, 4).map((item, i) => <span key={`${item.productId}-${i}`} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[var(--surface-2)] text-lg">{item.emoji}</span>)}
                  {order.items.length > 4 && <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[var(--surface-2)] text-[10px] font-extrabold">+{order.items.length - 4}</span>}
                  <span className="ml-1 hidden text-[10px] font-bold text-[var(--muted)] sm:block">{order.items.map((i) => i.name).slice(0, 2).join(", ")}{order.items.length > 2 ? "..." : ""}</span>
                </div>
                <div className="flex shrink-0 gap-1.5">
                  <button onClick={() => reorder(order)} className="btn-secondary btn-sm"><RotateCcw size={12} /> <span className="hidden sm:inline">{t("orderAgain")}</span></button>
                  <button onClick={() => setSelected(order)} className="btn-primary btn-sm">{t("details")} <ChevronRight size={12} /></button>
                </div>
              </div>
            </div>)}
        </div>}

      <Modal open={!!selected} onClose={() => setSelected(null)} title={selected ? `#${selected.id}` : ""}>
        {selected && <div className="space-y-4">
            <div className="flex items-center justify-between">
              <OrderStatusBadge status={selected.status} />
              <span className="text-[10px] font-bold text-[var(--muted)]">{selected.date}</span>
            </div>
            <OrderProgress status={selected.status} />
            <div className="space-y-2">
              {selected.items.map((item, i) => <div key={`${item.productId}-${i}`} className="flex items-center gap-2.5 rounded-xl bg-[var(--surface-2)] p-2.5">
                  <span className="flex h-9 w-9 items-center justify-center rounded-lg bg-[var(--surface)] text-lg">{item.emoji}</span>
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-[11px] font-extrabold">{item.name}</p>
                    <p className="text-[9px] text-[var(--muted)]">{item.qty} × {formatUZS(item.price)}</p>
                  </div>
                  <p className="text-[10px] font-extrabold">{formatUZS(item.price * item.qty)}</p>
                </div>)}
            </div>
            <div className="space-y-1.5 rounded-xl border p-3 text-[11px]">
              <div className="flex justify-between"><span className="text-[var(--muted)]">{t("subtotal")}</span><b>{formatUZS(selected.subtotal)}</b></div>
              {selected.discount > 0 && <div className="flex justify-between text-brand-600 dark:text-brand-400"><span>{t("discount")}</span><b>−{formatUZS(selected.discount)}</b></div>}
              <div className="flex justify-between"><span className="text-[var(--muted)]">{t("deliveryFee")}</span><b>{selected.delivery === 0 ? t("freeDelivery") : formatUZS(selected.delivery)}</b></div>
              <div className="flex justify-between border-t pt-1.5"><span className="font-extrabold">{t("total")}</span><b className="text-brand-700 dark:text-brand-400">{formatUZS(selected.total)}</b></div>
            </div>
            <div className="space-y-1.5 text-[11px]">
              <p className="flex items-start gap-1.5"><MapPin size={12} className="mt-0.5 shrink-0 text-brand-500" /> <span className="text-[var(--muted)]">{selected.address}</span></p>
              <p className="flex items-center gap-1.5"><Clock3 size={12} className="text-brand-500" /> <span className="text-[var(--muted)]">{selected.slot} · {selected.payment}</span></p>
            </div>
            <div className="flex gap-2">
              <button onClick={() => reorder(selected)} className="btn-secondary flex-1 btn-sm"><RotateCcw size={13} /> {t("orderAgain")}</button>
              {["confirmed", "preparing", "delivering"].includes(selected.status) && <Link to={`/tracking/${selected.id}`} className="btn-primary flex-1 btn-sm"><Truck size={13} /> {t("trackOrder")}</Link>}
            </div>
          </div>}
      </Modal>
    </div>;
};
